//! In-app file preview helpers (path safety, language guess, text load).

use crate::core::text::{decode_text, TextError};
use std::path::{Component, Path, PathBuf};

/// Default max bytes loaded into the in-app viewer.
pub const DEFAULT_PREVIEW_MAX: u64 = 512 * 1024; // 512 KiB

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FilePreview {
    pub path: String,
    pub language: String,
    pub content: String,
    pub size: u64,
    pub truncated: bool,
    pub binary: bool,
    pub absolute_path: String,
}

/// Reject `..` and absolute segments; resolve under `root`.
pub fn resolve_under_root(root: &Path, relative: &str) -> std::io::Result<PathBuf> {
    let root_canon = std::fs::canonicalize(root)?;
    resolve_under_canonical_root(&root_canon, relative)
}

/// Same checks as [`resolve_under_root`], for callers that already hold a canonical
/// root. Avoids re-canonicalizing the root for every path in a directory walk.
pub fn resolve_under_canonical_root(root_canon: &Path, relative: &str) -> std::io::Result<PathBuf> {
    let rel = relative.replace('\\', "/");
    if rel.is_empty() || rel == "." {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "empty relative path",
        ));
    }
    if Path::new(&rel).is_absolute() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "absolute paths are not allowed",
        ));
    }
    for c in Path::new(&rel).components() {
        match c {
            Component::Normal(_) => {}
            Component::CurDir => {}
            _ => {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidInput,
                    "path escapes project root",
                ));
            }
        }
    }

    let mut joined = root_canon.to_path_buf();
    for component in Path::new(&rel).components() {
        joined.push(component.as_os_str());
        let metadata = std::fs::symlink_metadata(&joined)?;
        if is_link(&metadata) {
            return Err(std::io::Error::new(
                std::io::ErrorKind::PermissionDenied,
                "symlinks and reparse points are not allowed",
            ));
        }
    }
    let full = std::fs::canonicalize(&joined)?;
    if !full.starts_with(root_canon) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "path is outside the project root",
        ));
    }
    Ok(full)
}

pub(crate) fn is_link(metadata: &std::fs::Metadata) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        metadata.file_attributes() & 0x400 != 0
    }
    #[cfg(not(windows))]
    {
        metadata.file_type().is_symlink()
    }
}

/// Opens `path` as a verified regular file, tying validation to the opened file handle:
/// - Rejects symlinks and Windows reparse points at the path before open (`symlink_metadata`).
/// - Uses `O_NOFOLLOW` on Unix and `FILE_FLAG_OPEN_REPARSE_POINT` on Windows so the kernel
///   never follows a symlink/junction at the final path component.
/// - Inspects `file.metadata()` (`fstat` on the open descriptor) and on Unix verifies that
///   `(dev, ino)` of the open descriptor matches the pre-open `symlink_metadata`, closing
///   the path-to-open TOCTOU swap window for the final component.
pub fn open_verified_regular_file(
    path: &Path,
) -> std::io::Result<(std::fs::File, std::fs::Metadata)> {
    let pre_meta = std::fs::symlink_metadata(path)?;
    if is_link(&pre_meta) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "symlinks and reparse points are not allowed",
        ));
    }
    if pre_meta.is_dir() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "path is a directory",
        ));
    }
    if !pre_meta.is_file() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "not a regular file",
        ));
    }

    let mut opts = std::fs::OpenOptions::new();
    opts.read(true);

    #[cfg(any(
        target_os = "macos",
        target_os = "ios",
        target_os = "freebsd",
        target_os = "openbsd",
        target_os = "netbsd"
    ))]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.custom_flags(0x0100); // O_NOFOLLOW on BSD / Darwin
    }

    #[cfg(all(target_os = "linux", target_arch = "aarch64"))]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.custom_flags(0o100000); // O_NOFOLLOW on Linux aarch64
    }

    #[cfg(all(target_os = "linux", not(target_arch = "aarch64")))]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.custom_flags(0o400000); // O_NOFOLLOW on Linux x86_64 / others
    }

    #[cfg(windows)]
    {
        use std::os::windows::fs::OpenOptionsExt;
        opts.custom_flags(0x0020_0000); // FILE_FLAG_OPEN_REPARSE_POINT
    }

    let file = opts.open(path)?;
    let post_meta = file.metadata()?;
    if is_link(&post_meta) || !post_meta.is_file() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "opened handle is not a regular non-link file",
        ));
    }

    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if pre_meta.dev() != post_meta.dev() || pre_meta.ino() != post_meta.ino() {
            return Err(std::io::Error::new(
                std::io::ErrorKind::PermissionDenied,
                "file changed identity (inode/device mismatch) during open",
            ));
        }
    }

    Ok((file, post_meta))
}

/// Reads up to `max_bytes` from a verified regular file handle.
pub fn read_verified_file_string(path: &Path, max_bytes: u64) -> std::io::Result<String> {
    use std::io::Read;
    let (file, meta) = open_verified_regular_file(path)?;
    if meta.len() > max_bytes {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!("file exceeds maximum size ({max_bytes} bytes)"),
        ));
    }
    let mut bytes = Vec::with_capacity(meta.len() as usize);
    file.take(max_bytes.saturating_add(1))
        .read_to_end(&mut bytes)?;
    if bytes.len() as u64 > max_bytes {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!("file grew beyond maximum size ({max_bytes} bytes)"),
        ));
    }
    String::from_utf8(bytes).map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))
}

/// Map file extension / name → highlight.js-style language id.
pub fn guess_language(path: &Path) -> &'static str {
    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();

    // Multi-dot / special names first
    if name.ends_with(".xaml.cs") || name.ends_with(".razor.cs") {
        return "csharp";
    }
    if name == "dockerfile" || name.starts_with("dockerfile.") {
        return "dockerfile";
    }
    if name == "makefile" || name == "gnumakefile" {
        return "makefile";
    }
    if name == "cargo.toml" || name == "pyproject.toml" {
        return "toml";
    }

    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();

    match ext.as_str() {
        "rs" => "rust",
        "ts" | "mts" | "cts" => "typescript",
        "tsx" => "typescript",
        "js" | "mjs" | "cjs" => "javascript",
        "jsx" => "javascript",
        "json" | "jsonc" => "json",
        "md" | "mdx" | "markdown" => "markdown",
        "py" | "pyw" => "python",
        "go" => "go",
        "java" => "java",
        "kt" | "kts" => "kotlin",
        "swift" => "swift",
        "cs" => "csharp",
        "fs" | "fsi" | "fsx" => "fsharp",
        "vb" => "vbnet",
        "xaml" | "axaml" => "xml",
        "xml" | "xsl" | "xslt" | "csproj" | "fsproj" | "vbproj" | "props" | "targets" | "resx"
        | "config" | "nuspec" | "plist" => "xml",
        "html" | "htm" | "cshtml" | "razor" | "vue" | "svelte" => "xml",
        "css" | "scss" | "less" => "css",
        "sql" => "sql",
        "sh" | "bash" | "zsh" => "bash",
        "ps1" | "psm1" => "powershell",
        "yml" | "yaml" => "yaml",
        "toml" => "toml",
        "ini" | "cfg" | "conf" | "env" => "ini",
        "c" | "h" => "c",
        "cpp" | "cc" | "cxx" | "hpp" | "hh" => "cpp",
        "rb" => "ruby",
        "php" => "php",
        "r" => "r",
        "lua" => "lua",
        "dart" => "dart",
        "gradle" => "gradle",
        "sln" => "plaintext",
        "txt" | "log" | "gitignore" | "dockerignore" | "editorconfig" => "plaintext",
        _ => "plaintext",
    }
}

pub fn load_preview(path: &Path, max_bytes: u64) -> std::io::Result<FilePreview> {
    let (file, meta) = open_verified_regular_file(path)?;
    let size = meta.len();
    let language = guess_language(path).to_string();
    let rel_display = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| path.display().to_string());

    let abs = dunce::simplified(path).display().to_string();

    if size == 0 {
        return Ok(FilePreview {
            path: rel_display,
            language,
            content: String::new(),
            size: 0,
            truncated: false,
            binary: false,
            absolute_path: abs,
        });
    }

    let to_read = size.min(max_bytes) as usize;
    let mut bytes = Vec::with_capacity(to_read);
    {
        use std::io::Read;
        file.take(to_read as u64).read_to_end(&mut bytes)?;
    }

    let truncated = size > max_bytes;
    let decoded = decode_text(&bytes, truncated);

    if decoded == Err(TextError::Binary) {
        return Ok(FilePreview {
            path: rel_display,
            language: "plaintext".into(),
            content: format!("[Binary file — {size} bytes. Open with an external app to view.]"),
            size,
            truncated: false,
            binary: true,
            absolute_path: abs,
        });
    }

    let mut content = decoded.map_err(|_| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            "Invalid text encoding: use UTF-8 or UTF-16 with BOM",
        )
    })?;
    if truncated {
        content.push_str(&format!(
            "\n\n// … truncated for preview ({size} bytes total, showing first {max_bytes}) …"
        ));
    }

    Ok(FilePreview {
        path: rel_display,
        language,
        content,
        size,
        truncated,
        binary: false,
        absolute_path: abs,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn resolve_blocks_parent_escape() {
        let dir = tempfile::tempdir().unwrap();
        let err = resolve_under_root(dir.path(), "../secret").unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::InvalidInput);
    }

    #[test]
    fn resolve_allows_nested() {
        let dir = tempfile::tempdir().unwrap();
        let nested = dir.path().join("a");
        fs::create_dir(&nested).unwrap();
        fs::write(nested.join("b.cs"), "class A {}").unwrap();
        let p = resolve_under_root(dir.path(), "a/b.cs").unwrap();
        assert!(p.ends_with("b.cs"));
    }

    #[test]
    fn guess_xaml_and_cs() {
        assert_eq!(guess_language(Path::new("MainWindow.xaml")), "xml");
        assert_eq!(guess_language(Path::new("MainWindow.xaml.cs")), "csharp");
        assert_eq!(guess_language(Path::new("App.csproj")), "xml");
        assert_eq!(guess_language(Path::new("Program.cs")), "csharp");
    }

    #[test]
    fn load_text_preview() {
        let dir = tempfile::tempdir().unwrap();
        let f = dir.path().join("hi.xaml");
        fs::write(&f, "<Grid />\n").unwrap();
        let prev = load_preview(&f, 1024).unwrap();
        assert!(!prev.binary);
        assert!(prev.content.contains("Grid"));
        assert_eq!(prev.language, "xml");
    }

    #[test]
    fn load_respects_max() {
        let dir = tempfile::tempdir().unwrap();
        let f = dir.path().join("big.txt");
        fs::write(&f, "abcdefghij").unwrap();
        let prev = load_preview(&f, 4).unwrap();
        assert!(prev.truncated);
        assert!(prev.content.starts_with("abcd"));
    }

    #[cfg(unix)]
    #[test]
    fn open_verified_regular_file_rejects_final_symlink_via_nofollow_and_load_preview_fails_closed()
    {
        let dir = tempfile::tempdir().unwrap();
        let outside = tempfile::tempdir().unwrap();
        let target = outside.path().join("secret.txt");
        fs::write(&target, "OUTSIDE_SECRET_PAYLOAD").unwrap();
        let link = dir.path().join("final_link.txt");
        std::os::unix::fs::symlink(&target, &link).unwrap();

        assert!(open_verified_regular_file(&link).is_err());
        assert!(load_preview(&link, 1024).is_err());
        assert!(read_verified_file_string(&link, 1024).is_err());
    }

    #[cfg(unix)]
    #[test]
    fn sandbox_rejects_symlinked_directory_components_and_escapes_before_open() {
        let root = tempfile::tempdir().unwrap();
        let outside = tempfile::tempdir().unwrap();
        fs::write(outside.path().join("secret.txt"), "OUTSIDE_SECRET_PAYLOAD").unwrap();
        std::os::unix::fs::symlink(outside.path(), root.path().join("linkdir")).unwrap();
        fs::write(root.path().join("inside.txt"), "INSIDE").unwrap();
        std::os::unix::fs::symlink(
            root.path().join("inside.txt"),
            root.path().join("alias.txt"),
        )
        .unwrap();

        // Intermediate symlink component pointing outside the root.
        let err = resolve_under_root(root.path(), "linkdir/secret.txt").unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::PermissionDenied);
        // Symlink to a file inside the root is still a link, so it is rejected too.
        let err = resolve_under_root(root.path(), "alias.txt").unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::PermissionDenied);
        // Traversal and absolute paths never reach the filesystem.
        for bad in ["../outside/secret.txt", "a/../../x", "/etc/passwd"] {
            assert!(
                resolve_under_root(root.path(), bad).is_err(),
                "{bad} was accepted"
            );
        }
        // The verified open itself refuses a symlink at the final component.
        assert!(open_verified_regular_file(&root.path().join("alias.txt")).is_err());
    }

    #[cfg(unix)]
    #[test]
    fn concurrent_swap_between_regular_file_and_symlink_never_yields_outside_content() {
        let root = tempfile::tempdir().unwrap();
        let outside = tempfile::tempdir().unwrap();
        let secret = outside.path().join("secret.txt");
        fs::write(&secret, "OUTSIDE_SECRET_PAYLOAD").unwrap();
        let path = root.path().join("target.txt");
        fs::write(&path, "INSIDE_PAYLOAD").unwrap();
        let flips = 2_000usize;

        // The swapper replaces `target.txt` with a symlink to the outside secret and back again.
        // Each replacement is one atomic rename, so the path always exists.
        let swap_path = path.clone();
        let swap_root = root.path().to_path_buf();
        let swap_secret = secret.clone();
        let swapper = std::thread::spawn(move || {
            for _ in 0..flips {
                let link_tmp = swap_root.join("swap.lnk");
                let _ = fs::remove_file(&link_tmp);
                std::os::unix::fs::symlink(&swap_secret, &link_tmp).unwrap();
                fs::rename(&link_tmp, &swap_path).unwrap();

                let reg_tmp = swap_root.join("swap.reg");
                fs::write(&reg_tmp, "INSIDE_PAYLOAD").unwrap();
                fs::rename(&reg_tmp, &swap_path).unwrap();
            }
        });

        let (mut opened, mut refused) = (0usize, 0usize);
        for _ in 0..flips * 2 {
            match read_verified_file_string(&path, 4096) {
                Ok(text) => {
                    assert!(
                        !text.contains("OUTSIDE"),
                        "verified open returned outside content during a swap"
                    );
                    assert_eq!(text, "INSIDE_PAYLOAD");
                    opened += 1;
                }
                Err(_) => refused += 1,
            }
        }
        swapper.join().expect("swapper thread panicked");
        assert_eq!(opened + refused, flips * 2);
        eprintln!("swap race: {opened} regular opens, {refused} refused");
    }
}


use super::tools::dispatch_tool;
use super::*;
use std::fs;
use tempfile::tempdir;

#[test]
fn mcp_initialize_and_tools_work() {
    let dir = tempdir().unwrap();
    fs::write(
        dir.path().join("lib.rs"),
        "pub fn greet(name: &str) -> String {\n    let msg = format!(\"hi {name}\");\n    msg\n}\n",
    )
    .unwrap();

    let init_resp = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    assert_eq!(init_resp["result"]["serverInfo"]["name"], "ptt-mcp");

    let list_resp = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    let tools = list_resp["result"]["tools"].as_array().unwrap();
    assert_eq!(tools.len(), 5);

    let map_resp = handle_jsonrpc_message(
            r#"{"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"ptt_get_project_map","arguments":{}}}"#,
            dir.path(),
        )
        .unwrap();
    let map_text = map_resp["result"]["content"][0]["text"].as_str().unwrap();
    assert!(map_text.contains("lib.rs"), "{map_text}");
    assert!(map_text.contains("pub fn greet"), "{map_text}");

    let pack_resp = handle_jsonrpc_message(
            r#"{"jsonrpc":"2.0","id":4,"method":"tools/call","params":{"name":"ptt_pack_files","arguments":{"paths":["lib.rs"],"skeleton":true}}}"#,
            dir.path(),
        )
        .unwrap();
    let pack_text = pack_resp["result"]["content"][0]["text"].as_str().unwrap();
    assert!(pack_text.contains("mode=\"skeleton\""), "{pack_text}");
    assert!(pack_text.contains("{ /* ... */ }"), "{pack_text}");
}

fn call(name: &str, args: Value, root: &Path) -> Value {
    let req = json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": { "name": name, "arguments": args }
    })
    .to_string();
    handle_jsonrpc_message(&req, root).unwrap()
}

#[test]
fn mcp_rejects_directories_outside_the_project_root() {
    let root = tempdir().unwrap();
    let outside = tempdir().unwrap();
    fs::write(outside.path().join("secret.rs"), "pub fn leaked() {}\n").unwrap();

    let absolute = call(
        "ptt_get_project_map",
        json!({ "directory": outside.path().to_string_lossy() }),
        root.path(),
    );
    assert_eq!(absolute["result"]["isError"], true, "{absolute}");
    let text = absolute["result"]["content"][0]["text"].as_str().unwrap();
    assert!(!text.contains("leaked"), "{text}");

    let traversal = call(
        "ptt_pack_files",
        json!({ "directory": "../../.." }),
        root.path(),
    );
    assert_eq!(traversal["result"]["isError"], true, "{traversal}");
}

#[test]
fn mcp_symbol_search_returns_src_first_and_pack_accepts_new_params() {
    let dir = tempdir().unwrap();
    fs::create_dir_all(dir.path().join("src")).unwrap();
    fs::create_dir_all(dir.path().join("tests")).unwrap();
    fs::write(
        dir.path().join("src/lib.rs"),
        "pub fn shared_target() -> u8 {\n    1\n}\n",
    )
    .unwrap();
    fs::write(
        dir.path().join("tests/a_test.rs"),
        "fn shared_target_check() -> u8 {\n    2\n}\n",
    )
    .unwrap();
    // `.dat` is neither a source nor a doc extension, so the source preset must drop it.
    fs::write(dir.path().join("notes.dat"), "# scratch notes\n").unwrap();

    let found = dispatch_tool(
        "ptt_search_symbols",
        &json!({"query": "shared_target"}),
        dir.path(),
    )
    .unwrap();
    let value: Value = serde_json::from_str(&found).unwrap();
    let paths: Vec<&str> = value["matches"]
        .as_array()
        .unwrap()
        .iter()
        .map(|m| m["path"].as_str().unwrap())
        .collect();
    assert_eq!(paths, vec!["src/lib.rs", "tests/a_test.rs"]);

    let packed = dispatch_tool("ptt_pack_files", &json!({"preset": "source"}), dir.path()).unwrap();
    assert!(packed.contains("shared_target"), "{packed}");
    assert!(
        !packed.contains("scratch notes"),
        "source preset kept notes.dat"
    );

    let budgeted = dispatch_tool(
        "ptt_pack_files",
        &json!({"max_tokens": 250, "git_diff": false}),
        dir.path(),
    )
    .unwrap();
    assert!(!budgeted.is_empty());
    assert!(
        dispatch_tool("ptt_pack_files", &json!({"max_tokens": 1}), dir.path()).is_err(),
        "impossible 1-token budget must return an explicit error instead of overflowing"
    );
    assert!(dispatch_tool("ptt_pack_files", &json!({"preset": "bogus"}), dir.path()).is_err());
}

#[test]
fn mcp_search_symbols_and_related_files() {
    let dir = tempdir().unwrap();
    fs::create_dir_all(dir.path().join("src")).unwrap();
    fs::write(dir.path().join("src/lib.rs"), "pub mod util;\n").unwrap();
    fs::write(
        dir.path().join("src/util.rs"),
        "pub fn helper_value() -> u32 {\n    42\n}\n",
    )
    .unwrap();

    let search = call(
        "ptt_search_symbols",
        json!({ "query": "helper" }),
        dir.path(),
    );
    let text = search["result"]["content"][0]["text"].as_str().unwrap();
    assert!(text.contains("\"name\": \"helper_value\""), "{text}");
    assert!(text.contains("\"startLine\": 1"), "{text}");
    assert!(text.contains("\"endLine\": 3"), "{text}");

    let related = call(
        "ptt_get_related_files",
        json!({ "path": "src/lib.rs" }),
        dir.path(),
    );
    let text = related["result"]["content"][0]["text"].as_str().unwrap();
    assert!(text.contains("src/util.rs"), "{text}");

    let missing = call(
        "ptt_get_related_files",
        json!({ "path": "src/nope.rs" }),
        dir.path(),
    );
    assert_eq!(missing["result"]["isError"], true, "{missing}");
}

#[test]
fn pending_cancellations_are_bounded_and_known_ids_refresh_in_place() {
    let mut set = HashSet::new();
    for i in 0..(MAX_PENDING_CANCELLATIONS * 3) {
        record_cancellation(&mut set, i.to_string());
    }
    assert_eq!(set.len(), MAX_PENDING_CANCELLATIONS);
    // A new id is dropped once the set is full.
    assert!(!record_cancellation(&mut set, "new-id".to_string()));
    assert_eq!(set.len(), MAX_PENDING_CANCELLATIONS);
    // An id already recorded can be re-recorded without growing the set.
    assert!(record_cancellation(&mut set, "0".to_string()));
    assert_eq!(set.len(), MAX_PENDING_CANCELLATIONS);
}

#[test]
fn mcp_negotiates_protocol_versions_and_validates_schemas_and_cancellation() {
    let dir = tempdir().unwrap();
    fs::write(dir.path().join("lib.rs"), "pub fn f() {}\n").unwrap();

    // 1. Version negotiation: supported revisions are echoed back exactly.
    for requested in ["2024-11-05", "2025-06-18", "2025-11-25"] {
        let req = json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": { "protocolVersion": requested }
        })
        .to_string();
        let resp = handle_jsonrpc_message(&req, dir.path()).unwrap();
        assert_eq!(resp["result"]["protocolVersion"], requested);
    }
    let unknown_ver = handle_jsonrpc_message(
            r#"{"jsonrpc":"2.0","id":2,"method":"initialize","params":{"protocolVersion":"1999-01-01"}}"#,
            dir.path(),
        )
        .unwrap();
    assert_eq!(
        unknown_ver["result"]["protocolVersion"],
        LATEST_MCP_PROTOCOL_VERSION
    );
    // 2026-07-28 is not implemented, so it must not be echoed back as supported.
    let unimplemented = handle_jsonrpc_message(
            r#"{"jsonrpc":"2.0","id":3,"method":"initialize","params":{"protocolVersion":"2026-07-28"}}"#,
            dir.path(),
        )
        .unwrap();
    assert_eq!(unimplemented["result"]["protocolVersion"], "2025-11-25");

    // 2. Strict JSON-RPC 2.0 envelope and schema validation (-32600 / -32602)
    let non_object = handle_jsonrpc_message("[1,2,3]", dir.path()).unwrap();
    assert_eq!(non_object["error"]["code"], -32600);

    let missing_jsonrpc =
        handle_jsonrpc_message(r#"{"id":1,"method":"ping"}"#, dir.path()).unwrap();
    assert_eq!(missing_jsonrpc["error"]["code"], -32600);

    let unknown_arg = call(
        "ptt_get_project_map",
        json!({ "unknown_field": true }),
        dir.path(),
    );
    assert_eq!(unknown_arg["error"]["code"], -32602, "{unknown_arg}");

    let wrong_type = call(
        "ptt_pack_files",
        json!({ "max_tokens": "not-a-number" }),
        dir.path(),
    );
    assert_eq!(wrong_type["error"]["code"], -32602, "{wrong_type}");

    let zero_budget = call("ptt_pack_files", json!({ "max_tokens": 0 }), dir.path());
    assert_eq!(zero_budget["error"]["code"], -32602, "{zero_budget}");

    // 3. Cancellation via `notifications/cancelled`
    assert!(handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","method":"notifications/cancelled","params":{"requestId":999}}"#,
        dir.path(),
    )
    .is_none());
    let cancelled = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":999,"method":"tools/list","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    assert_eq!(cancelled["error"]["code"], -32800, "{cancelled}");
}

#[test]
fn mcp_resources_and_tool_annotations() {
    let dir = tempdir().unwrap();
    fs::write(dir.path().join("main.rs"), "fn main() {}\n").unwrap();

    // 1. Verify initialize reports resources capability
    let init_resp = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    assert_eq!(
        init_resp["result"]["capabilities"]["resources"]["listChanged"],
        false
    );

    // 2. Verify all tool definitions contain MCP 2025-11-25 annotations
    let list_resp = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    let tools = list_resp["result"]["tools"].as_array().unwrap();
    for tool in tools {
        let ann = &tool["annotations"];
        assert_eq!(ann["readOnlyHint"], true);
        assert_eq!(ann["destructiveHint"], false);
        assert_eq!(ann["idempotentHint"], true);
        assert_eq!(ann["openWorldHint"], false);
    }

    // 3. Verify resources/list returns ptt://project/map and ptt://project/git-diff
    let res_list = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":3,"method":"resources/list","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    let resources = res_list["result"]["resources"].as_array().unwrap();
    assert_eq!(resources.len(), 2);
    let uris: Vec<&str> = resources.iter().filter_map(|r| r["uri"].as_str()).collect();
    assert!(uris.contains(&"ptt://project/map"));
    assert!(uris.contains(&"ptt://project/git-diff"));

    // 4. Verify resources/read reads ptt://project/map as text/markdown
    let res_read = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":4,"method":"resources/read","params":{"uri":"ptt://project/map"}}"#,
        dir.path(),
    )
    .unwrap();
    let contents = res_read["result"]["contents"].as_array().unwrap();
    assert_eq!(contents.len(), 1);
    assert_eq!(contents[0]["uri"], "ptt://project/map");
    assert_eq!(contents[0]["mimeType"], "text/markdown");
    assert!(contents[0]["text"]
        .as_str()
        .unwrap()
        .contains("Project Map"));

    // 5. Verify resources/read reads ptt://project/git-diff as application/json
    let res_read_diff = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":5,"method":"resources/read","params":{"uri":"ptt://project/git-diff"}}"#,
        dir.path(),
    )
    .unwrap();
    let contents_diff = res_read_diff["result"]["contents"].as_array().unwrap();
    assert_eq!(contents_diff.len(), 1);
    assert_eq!(contents_diff[0]["uri"], "ptt://project/git-diff");
    assert_eq!(contents_diff[0]["mimeType"], "application/json");
}

#[test]
fn mcp_prompts_list_and_get() {
    let dir = tempdir().unwrap();
    fs::create_dir_all(dir.path().join("src")).unwrap();
    fs::write(
        dir.path().join("src/lib.rs"),
        "pub fn core_logic() -> &'static str {\n    \"proscada\"\n}\n",
    )
    .unwrap();

    // 1. Verify initialize reports prompts capability
    let init_resp = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    assert_eq!(
        init_resp["result"]["capabilities"]["prompts"]["listChanged"],
        false
    );

    // 2. Verify prompts/list returns the 3 standard engineering prompts
    let list_resp = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":2,"method":"prompts/list","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    let prompts = list_resp["result"]["prompts"].as_array().unwrap();
    assert_eq!(prompts.len(), 3);
    let names: Vec<&str> = prompts.iter().filter_map(|p| p["name"].as_str()).collect();
    assert_eq!(
        names,
        vec!["architecture_review", "security_audit", "git_diff_review"]
    );

    // 3. Verify prompts/get for architecture_review (with and without focus_path)
    let arch_get = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":3,"method":"prompts/get","params":{"name":"architecture_review","arguments":{"focus_path":"src/lib.rs"}}}"#,
        dir.path(),
    )
    .unwrap();
    assert_eq!(
        arch_get["result"]["description"],
        "Deep architectural, modularity, and dependency-graph review of the repository"
    );
    let arch_text = arch_get["result"]["messages"][0]["content"]["text"]
        .as_str()
        .unwrap();
    assert!(arch_text.contains("Architecture & Dependency-Graph Review Request"));
    assert!(arch_text.contains("src/lib.rs"));
    assert!(arch_text.contains("core_logic"));

    // 4. Verify prompts/get for security_audit
    let sec_get = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":4,"method":"prompts/get","params":{"name":"security_audit"}}"#,
        dir.path(),
    )
    .unwrap();
    let sec_text = sec_get["result"]["messages"][0]["content"]["text"]
        .as_str()
        .unwrap();
    assert!(sec_text.contains("Security & Secret-Exposure Audit Request"));
    assert!(sec_text.contains("Path traversal & sandboxing"));

    // 5. Verify prompts/get for git_diff_review
    let git_get = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":5,"method":"prompts/get","params":{"name":"git_diff_review"}}"#,
        dir.path(),
    )
    .unwrap();
    let git_text = git_get["result"]["messages"][0]["content"]["text"]
        .as_str()
        .unwrap();
    assert!(git_text.contains("Pre-Merge Git Diff Review Request"));

    // 6. Verify error handling for missing name and unknown prompt
    let missing_name = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":6,"method":"prompts/get","params":{}}"#,
        dir.path(),
    )
    .unwrap();
    assert_eq!(missing_name["error"]["code"], -32602);

    let unknown_prompt = handle_jsonrpc_message(
        r#"{"jsonrpc":"2.0","id":7,"method":"prompts/get","params":{"name":"non_existent"}}"#,
        dir.path(),
    )
    .unwrap();
    assert_eq!(unknown_prompt["error"]["code"], -32602);
}

#[test]
fn mcp_pack_files_supports_pinned_paths_and_budget() {
    let dir = tempdir().unwrap();
    fs::create_dir_all(dir.path().join("src")).unwrap();
    fs::write(
        dir.path().join("src/pinned.rs"),
        "pub fn pinned_fn() -> usize { 42 }\n",
    )
    .unwrap();
    fs::write(
        dir.path().join("src/drop_me.rs"),
        (0..100)
            .map(|i| format!("pub fn filler_{i}() -> usize {{ {i} }}\n"))
            .collect::<String>(),
    )
    .unwrap();

    let req = json!({
        "jsonrpc": "2.0",
        "id": 10,
        "method": "tools/call",
        "params": {
            "name": "ptt_pack_files",
            "arguments": {
                "pinned_paths": ["src/pinned.rs"],
                "max_tokens": 500
            }
        }
    })
    .to_string();

    let resp = handle_jsonrpc_message(&req, dir.path()).unwrap();
    assert_eq!(resp["result"]["isError"], false, "{resp}");
    let text = resp["result"]["content"][0]["text"].as_str().unwrap();
    assert!(
        text.contains("pinned.rs"),
        "pinned file must be preserved: {text}"
    );
    assert!(
        !text.contains("drop_me.rs"),
        "non-pinned file must be dropped: {text}"
    );
}

#[test]
fn mcp_pack_files_accepts_tokenizer_and_prompt() {
    let dir = tempdir().unwrap();
    fs::create_dir_all(dir.path().join("src")).unwrap();
    fs::write(
        dir.path().join("src/lib.rs"),
        "pub fn core_logic() -> &'static str { \"valid\" }\n",
    )
    .unwrap();

    let req = json!({
        "jsonrpc": "2.0",
        "id": 11,
        "method": "tools/call",
        "params": {
            "name": "ptt_pack_files",
            "arguments": {
                "paths": ["src/lib.rs"],
                "tokenizer": "claude",
                "prompt": "Review this module"
            }
        }
    })
    .to_string();

    let resp = handle_jsonrpc_message(&req, dir.path()).unwrap();
    assert_eq!(resp["result"]["isError"], false, "{resp}");
    let text = resp["result"]["content"][0]["text"].as_str().unwrap();
    assert!(text.contains("src/lib.rs"), "{text}");
    assert!(text.contains("<task_instructions>"), "{text}");
    assert!(text.contains("Review this module"), "{text}");

    // Invalid tokenizer must be rejected
    let invalid_req = json!({
        "jsonrpc": "2.0",
        "id": 12,
        "method": "tools/call",
        "params": {
            "name": "ptt_pack_files",
            "arguments": {
                "tokenizer": "invalid_model"
            }
        }
    })
    .to_string();
    let invalid_resp = handle_jsonrpc_message(&invalid_req, dir.path()).unwrap();
    assert_eq!(invalid_resp["error"]["code"], -32602, "{invalid_resp}");

    // Also verify get_git_context works cleanly via snapshot
    let git_req = json!({
        "jsonrpc": "2.0",
        "id": 13,
        "method": "tools/call",
        "params": {
            "name": "ptt_get_git_context",
            "arguments": {}
        }
    })
    .to_string();
    let git_resp = handle_jsonrpc_message(&git_req, dir.path()).unwrap();
    assert_eq!(git_resp["result"]["isError"], false, "{git_resp}");
}


//! MCP tool surface: JSON schemas, argument validation, the project-root sandbox, and tool dispatch.
//!
//! `mcp.rs` owns the JSON-RPC envelope and calls [`dispatch_tool`] for each `tools/call`.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex, MutexGuard, OnceLock};

use rayon::prelude::*;
use serde_json::{json, Value};

use ptt::core::budget::fit_workspace_to_bpe_budget;
use ptt::core::git::compute_git_diff;
use ptt::core::output::{
    architectural_tier, write_output_with_stats, OutputFormat, WriteOptions, DEFAULT_MAX_FILE_SIZE,
};
use ptt::core::preview::{read_verified_file_string, resolve_under_canonical_root};
use ptt::core::secrets::redact_secrets;
use ptt::core::skeleton::{extract_skeleton, find_symbols, language_for_path, SymbolMatch};
use ptt::core::tokenizer::{count_tokens, estimate_tokens_from_bytes, TokenizerModel};
use ptt::core::walker::{normalize_rel_path, SelectionMatcher};
use ptt::core::workspace::{WorkspaceIndex, WorkspaceSnapshot};

use crate::cli::{filter_entries_for_cli_with_context, parse_preset, PackArgs};

/// Files above this size are never read for skeletons or symbol search.
const MAP_SKELETON_MAX_BYTES: u64 = 128 * 1024;
const MAP_SKELETON_MAX_FILES: usize = 15;
const SYMBOL_MAX_FILE_BYTES: u64 = 512 * 1024;
const SYMBOL_MAX_RESULTS: usize = 100;

/// Process-local index, so repeated MCP calls reuse the dependency graph built by earlier calls.
fn mcp_workspace_index() -> &'static WorkspaceIndex {
    static INDEX: OnceLock<WorkspaceIndex> = OnceLock::new();
    INDEX.get_or_init(WorkspaceIndex::default)
}

/// Serializes index use: each scan bumps a shared revision, and a concurrent scan would supersede it.
fn mcp_index_lock() -> MutexGuard<'static, ()> {
    static LOCK: Mutex<()> = Mutex::new(());
    LOCK.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

fn get_or_scan_snapshot(root: &Path) -> Result<Arc<WorkspaceSnapshot>, String> {
    let _index_guard = mcp_index_lock();
    let index = mcp_workspace_index();
    if let Some(current) = index.current_snapshot() {
        if current.root == root && index.get(root, current.revision).is_ok() {
            return Ok(current);
        }
    }
    index.scan(root)
}

pub(super) fn tool_definitions() -> Value {
    let read_only_annotations = json!({
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
    });

    json!([
        {
            "name": "ptt_get_project_map",
            "description": "Returns the ignore-aware directory tree, token estimates per file, and optional AST skeletons of key modules.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "directory": {
                        "type": "string",
                        "description": "Optional project root directory (defaults to server working directory)."
                    },
                    "include_skeletons": {
                        "type": "boolean",
                        "description": "Include AST skeletons of top source modules (default: true)."
                    }
                },
                "additionalProperties": false
            },
            "annotations": read_only_annotations
        },
        {
            "name": "ptt_pack_files",
            "description": "Packs requested files (or the whole repository) into LLM-ready XML/Markdown/JSON respecting .gitignore, .pttignore, and secret redaction.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "directory": {
                        "type": "string",
                        "description": "Optional project root directory."
                    },
                    "paths": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Relative file or directory paths to pack. If omitted or empty, packs all clean files."
                    },
                    "pinned_paths": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Relative file paths that must never be dropped when fitting to max_tokens."
                    },
                    "skeleton": {
                        "type": "boolean",
                        "description": "Pack files in AST Skeleton mode (signatures & types only)."
                    },
                    "format": {
                        "type": "string",
                        "enum": ["xml", "markdown", "json", "plain"],
                        "description": "Output format (default: xml)."
                    },
                    "preset": {
                        "type": "string",
                        "enum": ["source", "docs", "all"],
                        "description": "Keep only source files, source and docs, or every file (default: all)."
                    },
                    "max_tokens": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Fit the pack within this many tokens (exact BPE count). Files are skeletonized or dropped by priority."
                    },
                    "git_diff": {
                        "type": "boolean",
                        "description": "Append the unified git diff as <git_diff> (default: false)."
                    },
                    "tokenizer": {
                        "type": "string",
                        "enum": ["o200k_base", "cl100k_base", "claude", "gemini"],
                        "description": "Tokenizer model for BPE token counting (default: o200k_base)."
                    },
                    "prompt": {
                        "type": "string",
                        "description": "Optional task instructions appended inside <task_instructions> at the end of the pack."
                    }
                },
                "additionalProperties": false
            },
            "annotations": read_only_annotations
        },
        {
            "name": "ptt_get_git_context",
            "description": "Returns modified/untracked files, branch changes, recent commits, and the unified git diff.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "directory": {
                        "type": "string",
                        "description": "Optional project root directory."
                    }
                },
                "additionalProperties": false
            },
            "annotations": read_only_annotations
        },
        {
            "name": "ptt_get_related_files",
            "description": "Returns the 1-hop imports, importers, and matching tests of one file, from the project's dependency graph.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "path": {
                        "type": "string",
                        "description": "Relative path of the file, for example src/core/git.rs."
                    },
                    "directory": {
                        "type": "string",
                        "description": "Optional project root directory inside the server's project root."
                    }
                },
                "required": ["path"],
                "additionalProperties": false
            },
            "annotations": read_only_annotations
        },
        {
            "name": "ptt_search_symbols",
            "description": "Finds functions, methods, types, classes, interfaces, or traits whose name contains the query (case-insensitive) and returns each definition's exact source with its line range.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "query": {
                        "type": "string",
                        "description": "Substring of the symbol name, for example compute or Config."
                    },
                    "paths": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Optional relative files or directories to limit the search to."
                    },
                    "directory": {
                        "type": "string",
                        "description": "Optional project root directory inside the server's project root."
                    }
                },
                "required": ["query"],
                "additionalProperties": false
            },
            "annotations": read_only_annotations
        }
    ])
}

/// Validates tool arguments against the declared JSON schema before dispatching.
pub(super) fn validate_tool_arguments(tool_name: &str, args: &Value) -> Result<(), String> {
    let Some(obj) = args.as_object() else {
        return Err("arguments must be a JSON object".into());
    };
    let check_known = |allowed: &[&str]| -> Result<(), String> {
        for key in obj.keys() {
            if !allowed.contains(&key.as_str()) {
                return Err(format!("unknown argument '{key}' for tool {tool_name}"));
            }
        }
        Ok(())
    };
    let check_opt_str = |key: &str| -> Result<(), String> {
        if let Some(v) = obj.get(key) {
            if !v.is_null() && !v.is_string() {
                return Err(format!("argument '{key}' must be a string"));
            }
        }
        Ok(())
    };
    let check_opt_bool = |key: &str| -> Result<(), String> {
        if let Some(v) = obj.get(key) {
            if !v.is_null() && !v.is_boolean() {
                return Err(format!("argument '{key}' must be a boolean"));
            }
        }
        Ok(())
    };
    let check_opt_str_array = |key: &str| -> Result<(), String> {
        if let Some(v) = obj.get(key) {
            if !v.is_null() {
                let Some(arr) = v.as_array() else {
                    return Err(format!("argument '{key}' must be an array of strings"));
                };
                if !arr.iter().all(Value::is_string) {
                    return Err(format!("argument '{key}' must contain only strings"));
                }
            }
        }
        Ok(())
    };

    match tool_name {
        "ptt_get_project_map" => {
            check_known(&["directory", "include_skeletons"])?;
            check_opt_str("directory")?;
            check_opt_bool("include_skeletons")?;
        }
        "ptt_pack_files" => {
            check_known(&[
                "directory",
                "paths",
                "pinned_paths",
                "skeleton",
                "format",
                "preset",
                "max_tokens",
                "git_diff",
                "tokenizer",
                "prompt",
            ])?;
            check_opt_str("directory")?;
            check_opt_str_array("paths")?;
            check_opt_str_array("pinned_paths")?;
            check_opt_bool("skeleton")?;
            check_opt_str("format")?;
            check_opt_str("preset")?;
            check_opt_bool("git_diff")?;
            check_opt_str("tokenizer")?;
            check_opt_str("prompt")?;
            if let Some(v) = obj.get("max_tokens") {
                if !v.is_null() && v.as_u64().is_none_or(|n| n == 0) {
                    return Err("argument 'max_tokens' must be a positive integer".into());
                }
            }
            if let Some(v) = obj.get("tokenizer").and_then(Value::as_str) {
                TokenizerModel::try_parse(v)?;
            }
        }
        "ptt_get_git_context" => {
            check_known(&["directory"])?;
            check_opt_str("directory")?;
        }
        "ptt_get_related_files" => {
            check_known(&["path", "directory"])?;
            check_opt_str("directory")?;
            match obj.get("path").and_then(Value::as_str).map(str::trim) {
                Some(s) if !s.is_empty() => {}
                _ => return Err("required argument 'path' must be a non-empty string".into()),
            }
        }
        "ptt_search_symbols" => {
            check_known(&["query", "paths", "directory"])?;
            check_opt_str("directory")?;
            check_opt_str_array("paths")?;
            match obj.get("query").and_then(Value::as_str).map(str::trim) {
                Some(s) if !s.is_empty() => {}
                _ => return Err("required argument 'query' must be a non-empty string".into()),
            }
        }
        _ => {}
    }
    Ok(())
}

/// Resolves the project root for a tool call. The server's `default_root` is the sandbox:
/// a requested directory must stay inside it, including through symlinks.
fn resolve_root(args: &Value, default_root: &Path) -> Result<PathBuf, String> {
    let canon_default = default_root.canonicalize().map_err(|e| {
        format!(
            "cannot canonicalize project root {}: {e}",
            default_root.display()
        )
    })?;
    let requested = args
        .get("directory")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty() && *s != ".");
    let Some(requested) = requested else {
        return Ok(canon_default);
    };

    let resolved = if Path::new(requested).is_absolute() {
        Path::new(requested)
            .canonicalize()
            .map_err(|e| format!("cannot canonicalize directory {requested}: {e}"))?
    } else {
        resolve_under_canonical_root(&canon_default, requested)
            .map_err(|e| format!("directory {requested} is not accessible: {e}"))?
    };
    if !resolved.starts_with(&canon_default) {
        return Err(format!(
            "directory {requested} is outside the server's project root"
        ));
    }
    if !resolved.is_dir() {
        return Err(format!("{requested} is not a directory"));
    }
    Ok(resolved)
}

#[cfg(test)]
pub(super) fn dispatch_tool(
    name: &str,
    args: &Value,
    default_root: &Path,
) -> Result<String, String> {
    dispatch_tool_cancellable(name, args, default_root, Arc::new(AtomicBool::new(false)))
}

pub(super) fn dispatch_tool_cancellable(
    name: &str,
    args: &Value,
    default_root: &Path,
    cancelled: Arc<AtomicBool>,
) -> Result<String, String> {
    let root = resolve_root(args, default_root)?;
    match name {
        "ptt_get_project_map" => {
            let include_skeletons = args
                .get("include_skeletons")
                .and_then(Value::as_bool)
                .unwrap_or(true);
            let snapshot = get_or_scan_snapshot(&root)?;
            let files: Vec<_> = snapshot.entries.iter().filter(|e| !e.is_dir).collect();

            let mut out = String::new();
            out.push_str(&format!(
                "# Project Map ({} files)\n\n## Directory Tree & Token Estimates\n",
                files.len()
            ));
            for f in &files {
                let rel = normalize_rel_path(&f.path);
                let size = f.size.unwrap_or(0);
                let tok = estimate_tokens_from_bytes(size);
                out.push_str(&format!("- `{rel}` (~{tok} tokens, {size} bytes)\n"));
            }

            if include_skeletons {
                out.push_str("\n## Key Module AST Skeletons\n");
                out.push_str("(exact BPE tokens: full file \u{2192} skeleton)\n");
                // Size is checked from metadata before any read. Core modules come first.
                let mut candidates: Vec<_> = files
                    .iter()
                    .filter(|f| language_for_path(&f.path) != "other")
                    .filter(|f| f.size.is_some_and(|s| s <= MAP_SKELETON_MAX_BYTES))
                    .copied()
                    .collect();
                candidates.sort_by_cached_key(|f| {
                    let rel = normalize_rel_path(&f.path);
                    (architectural_tier(&rel), rel)
                });
                for f in candidates.into_iter().take(MAP_SKELETON_MAX_FILES) {
                    if cancelled.load(Ordering::Relaxed) {
                        return Err("operation cancelled".into());
                    }
                    let rel = normalize_rel_path(&f.path);
                    let lang = language_for_path(&f.path);
                    let Ok(full) = resolve_under_canonical_root(&root, &rel) else {
                        continue;
                    };
                    let Ok(content) = read_verified_file_string(&full, MAP_SKELETON_MAX_BYTES)
                    else {
                        continue;
                    };
                    let redacted = redact_secrets(&content);
                    let skel = extract_skeleton(&redacted, lang);
                    out.push_str(&format!(
                        "\n### `{rel}` ({} \u{2192} {} tokens)\n```{lang}\n{skel}\n```\n",
                        count_tokens(&redacted),
                        count_tokens(&skel)
                    ));
                }
            }
            Ok(out)
        }
        "ptt_pack_files" => {
            let snapshot = get_or_scan_snapshot(&root)?;
            let requested: Vec<String> = args
                .get("paths")
                .and_then(Value::as_array)
                .map(|arr| {
                    arr.iter()
                        .filter_map(Value::as_str)
                        .map(|s| s.to_string())
                        .collect()
                })
                .unwrap_or_default();

            let pinned_paths: Vec<String> = args
                .get("pinned_paths")
                .and_then(Value::as_array)
                .map(|arr| {
                    arr.iter()
                        .filter_map(Value::as_str)
                        .map(|s| s.to_string())
                        .collect()
                })
                .unwrap_or_default();
            let pinned_set: HashSet<String> = pinned_paths
                .iter()
                .map(|p| normalize_rel_path(Path::new(p)))
                .collect();

            let selected_entries: Vec<_> = if requested.is_empty() {
                snapshot
                    .entries
                    .iter()
                    .filter(|e| !e.is_dir)
                    .cloned()
                    .collect()
            } else {
                snapshot.selected(&requested)
            };

            let skeleton = args
                .get("skeleton")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let format = match args
                .get("format")
                .and_then(Value::as_str)
                .unwrap_or("xml")
                .to_ascii_lowercase()
                .as_str()
            {
                "xml" => OutputFormat::Xml,
                "markdown" | "md" => OutputFormat::Markdown,
                "json" => OutputFormat::Json,
                "plain" | "txt" | "text" => OutputFormat::Plain,
                other => {
                    return Err(format!(
                        "unknown format '{other}' (use xml|markdown|json|plain)"
                    ))
                }
            };

            let preset = args
                .get("preset")
                .and_then(Value::as_str)
                .map(parse_preset)
                .transpose()?;
            let max_tokens = args
                .get("max_tokens")
                .and_then(Value::as_u64)
                .map(|n| usize::try_from(n).unwrap_or(usize::MAX));
            let git_diff = args
                .get("git_diff")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let tokenizer_model = match args.get("tokenizer").and_then(Value::as_str) {
                Some(s) => TokenizerModel::try_parse(s)?,
                None => TokenizerModel::O200kBase,
            };
            let task_prompt = args
                .get("prompt")
                .and_then(Value::as_str)
                .map(str::to_string)
                .filter(|s| !s.trim().is_empty());

            // Same selection as `ptt pack`: preset and the heuristic budget pass first.
            let pack_args = PackArgs {
                dir: root.clone(),
                preset,
                skeleton,
                max_tokens,
                pinned_paths,
                tokenizer_model,
                task_prompt: task_prompt.clone(),
                ..Default::default()
            };
            let (selected_entries, skeleton_files) = filter_entries_for_cli_with_context(
                selected_entries,
                &root,
                &pack_args,
                Some(&snapshot.git_context),
                Some(snapshot.dependency_graph()),
            )?;

            let computed_diff = if git_diff {
                compute_git_diff(&root, 256 * 1024)
            } else {
                None
            };

            let modified_files = snapshot
                .git_context
                .modified_files
                .iter()
                .cloned()
                .collect();

            let mut opts = WriteOptions {
                format,
                include_file_summary: true,
                max_file_size: DEFAULT_MAX_FILE_SIZE,
                redact_secrets: true,
                skeleton_all: skeleton,
                skeleton_files,
                git_diff: computed_diff,
                task_prompt,
                tokenizer_model,
                compute_bpe_tokens: true,
                modified_files,
            };

            let is_cancelled = {
                let c = Arc::clone(&cancelled);
                move || c.load(Ordering::Relaxed)
            };

            let mut buf = Vec::new();
            if let Some(budget) = max_tokens {
                let (entries, skeleton_files, workspace) = fit_workspace_to_bpe_budget(
                    selected_entries,
                    &root,
                    &opts,
                    budget,
                    &pinned_set,
                    Some(snapshot.dependency_graph()),
                    &is_cancelled,
                )?;
                opts.skeleton_files = skeleton_files;
                let _ = workspace
                    .render_with_stats(&mut buf, &entries, &opts.skeleton_files, opts.skeleton_all)
                    .map_err(|e| e.to_string())?;
            } else {
                let _ = write_output_with_stats(
                    &mut buf,
                    &selected_entries,
                    &root,
                    &opts,
                    &is_cancelled,
                )
                .map_err(|e| e.to_string())?;
            }
            String::from_utf8(buf).map_err(|e| e.to_string())
        }
        "ptt_get_git_context" => {
            let snapshot = get_or_scan_snapshot(&root)?;
            let ctx = &snapshot.git_context;
            let diff = compute_git_diff(&root, 256 * 1024).unwrap_or_default();
            let redacted_diff = redact_secrets(&diff);
            let summary = json!({
                "isGitRepo": ctx.is_git_repo,
                "currentBranch": ctx.current_branch,
                "baseBranch": ctx.base_branch,
                "modifiedFiles": ctx.modified_files,
                "branchChangedFiles": ctx.branch_changed_files,
                "recentCommits": ctx.recent_commits,
                "diff": redacted_diff,
            });
            serde_json::to_string_pretty(&summary).map_err(|e| e.to_string())
        }
        "ptt_get_related_files" => {
            let path = args
                .get("path")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .ok_or("ptt_get_related_files requires a non-empty `path`")?;
            let snapshot = get_or_scan_snapshot(&root)?;
            let normalized = normalize_rel_path(Path::new(path));
            if !snapshot
                .entries
                .iter()
                .any(|e| !e.is_dir && normalize_rel_path(&e.path) == normalized)
            {
                return Err(format!("file not found in project: {path}"));
            }
            let related = snapshot.dependency_graph().related_for(&normalized);
            serde_json::to_string_pretty(&related).map_err(|e| e.to_string())
        }
        "ptt_search_symbols" => {
            let query = args
                .get("query")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .ok_or("ptt_search_symbols requires a non-empty `query`")?;
            let requested: Vec<String> = args
                .get("paths")
                .and_then(Value::as_array)
                .map(|arr| {
                    arr.iter()
                        .filter_map(Value::as_str)
                        .map(str::to_string)
                        .collect()
                })
                .unwrap_or_default();
            let matcher = (!requested.is_empty()).then(|| SelectionMatcher::new(&requested));
            let snapshot = get_or_scan_snapshot(&root)?;
            let mut candidates: Vec<&ptt::core::walker::DirEntryMeta> = snapshot
                .entries
                .iter()
                .filter(|e| !e.is_dir)
                .filter(|e| language_for_path(&e.path) != "other")
                .filter(|e| matcher.as_ref().is_none_or(|m| m.is_selected(&e.path)))
                .filter(|e| e.size.is_none_or(|s| s <= SYMBOL_MAX_FILE_BYTES))
                .collect();
            // Architectural tiers first, so `src/` is searched and returned before tests and benchmarks.
            candidates.sort_by_cached_key(|e| {
                let rel = normalize_rel_path(&e.path);
                (architectural_tier(&rel), rel)
            });

            // Read and parse in parallel. The indexed collect keeps the tier order.
            let per_file: Vec<(String, Vec<SymbolMatch>)> = candidates
                .par_iter()
                .filter_map(|e| {
                    if cancelled.load(Ordering::Relaxed) {
                        return None;
                    }
                    let rel = normalize_rel_path(&e.path);
                    let lang = language_for_path(&e.path);
                    let full = resolve_under_canonical_root(&root, &rel).ok()?;
                    let raw = read_verified_file_string(&full, SYMBOL_MAX_FILE_BYTES).ok()?;
                    // Redact before parsing, so names and spans come from the masked text.
                    let content = redact_secrets(&raw).into_owned();
                    let hits = find_symbols(&content, lang, query);
                    (!hits.is_empty()).then_some((rel, hits))
                })
                .collect();

            if cancelled.load(Ordering::Relaxed) {
                return Err("operation cancelled".into());
            }

            let mut matches = Vec::new();
            let mut truncated = false;
            'files: for (rel, hits) in per_file {
                for hit in hits {
                    if matches.len() >= SYMBOL_MAX_RESULTS {
                        truncated = true;
                        break 'files;
                    }
                    matches.push(json!({
                        "path": rel,
                        "name": hit.name,
                        "kind": hit.kind,
                        "startLine": hit.start_line,
                        "endLine": hit.end_line,
                        "source": hit.source,
                    }));
                }
            }
            serde_json::to_string_pretty(&json!({
                "query": query,
                "truncated": truncated,
                "matches": matches,
            }))
            .map_err(|e| e.to_string())
        }
        other => Err(format!("Unknown MCP tool: {other}")),
    }
}
